// NetworkInterface cloud-init network-config v2 shaped. Mammoth never allocates addresses; all `addresses` are caller-provided.
type NetworkInterface struct {
	Addresses *[]string `json:"addresses,omitempty"`

	// Bond Bonds name bond0, bond1, … in declaration order (independent of the entry's position in the network array); vlan.link references that name. params speak kernel names (miimon, lacp_rate, …) — cloud-init v2/netplan spellings (mii-monitor-interval, lacp-rate, arp-ip-targets, …) are accepted and folded onto the canonical names; the same key declared twice under two spellings rejects, unknown keys reject. Multi-value targets (arp-ip-targets) take a JSON array. params without miimon or arp_interval get the default miimon=100 — the kernel's own default since v4.18 (older kernels default to 0: link monitoring off); a declared arp_interval is ARP monitoring and excludes miimon. The declared bonds are cross-checked against the live system after install (INSTALL_BOND_MISMATCH on member/mode/miimon drift).
	Bond *struct {
		Interfaces []struct {
			// Match Selection stability order is mac > pci_address > name.
			Match   InterfaceMatch `json:"match"`
			SetName *string        `json:"set_name,omitempty"`
		} `json:"interfaces"`

		// Mode Kernel bonding mode: balance-rr(0) | active-backup(1) | balance-xor(2) | broadcast(3) | 802.3ad(4) | balance-tlb(5) | balance-alb(6). Numeric aliases normalize to the name; unknown values are rejected at render (RENDER_FAILED).
		Mode   string                  `json:"mode"`
		Params *map[string]interface{} `json:"params,omitempty"`
	} `json:"bond,omitempty"`

	// Match Selection stability order is mac > pci_address > name.
	Match       *InterfaceMatch `json:"match,omitempty"`
	Mtu         *int            `json:"mtu,omitempty"`
	Nameservers *Nameservers    `json:"nameservers,omitempty"`
	Routes      *[]Route        `json:"routes,omitempty"`
	SetName     *string         `json:"set_name,omitempty"`
	Vlan        *struct {
		Id   int    `json:"id"`
		Link string `json:"link"`
	} `json:"vlan,omitempty"`
}

